-- This program creates the reviews table for ADM-02. A customer and
-- a listing supplier may each leave one review of the other party on
-- a completed booking: one row per (booking, reviewer), so a single
-- booking can carry up to two reviews, one per direction.
--
-- File:   V9__create_reviews_table.sql
-- Course: AUCSC 325
--

CREATE TABLE reviews (
    -- To identify each review; generated by the database
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- To point at the completed booking this review is about
    booking_id    BIGINT NOT NULL,
    -- To record who left this review
    reviewer_id   BIGINT NOT NULL,
    -- To record who this review is about
    reviewee_id   BIGINT NOT NULL,
    -- To store the 1-5 star rating
    rating        INTEGER NOT NULL,
    -- To let the reviewer leave an optional comment
    comment       VARCHAR(1000),
    -- To record when this review was added
    created_at    TIMESTAMP(6) WITH TIME ZONE NOT NULL DEFAULT now(),
    -- To keep the rating inside the 1-5 star scale
    CONSTRAINT ck_reviews_rating_range
        CHECK (rating BETWEEN 1 AND 5),
    -- To reject a reviewer rating themselves
    CONSTRAINT ck_reviews_reviewer_not_reviewee
        CHECK (reviewer_id <> reviewee_id),
    -- To keep a review only when its booking still exists
    CONSTRAINT fk_reviews_booking
        FOREIGN KEY (booking_id) REFERENCES bookings (id),
    -- To keep a review only when its reviewer still exists
    CONSTRAINT fk_reviews_reviewer
        FOREIGN KEY (reviewer_id) REFERENCES users (id),
    -- To keep a review only when its reviewee still exists
    CONSTRAINT fk_reviews_reviewee
        FOREIGN KEY (reviewee_id) REFERENCES users (id),
    -- To allow at most one review per booking per reviewer
    CONSTRAINT uq_reviews_booking_reviewer
        UNIQUE (booking_id, reviewer_id)
);

-- To look up the reviews left on a booking
CREATE INDEX idx_reviews_booking_id ON reviews (booking_id);

-- To look up the reviews received by a user
CREATE INDEX idx_reviews_reviewee_id ON reviews (reviewee_id);
